package com.jnapanam.sportszone.tournament.dto;import com.jnapanam.sportszone.tournament.model.*;import java.math.BigDecimal;import java.time.LocalDate;import java.util.UUID;public record TournamentResponse(UUID id,String code,String name,String description,String sportCode,String organizerName,TournamentFormat format,TournamentStatus status,LocalDate registrationOpens,LocalDate registrationCloses,LocalDate startDate,LocalDate endDate,int teamSize,int maxTeams,long registeredTeams,BigDecimal entryFee){public static TournamentResponse from(Tournament t,long teams){return new TournamentResponse(t.getId(),t.getCode(),t.getName(),t.getDescription(),t.getSport().getCode(),t.getOrganizer().getFullName(),t.getFormat(),t.getStatus(),t.getRegistrationOpens(),t.getRegistrationCloses(),t.getStartDate(),t.getEndDate(),t.getTeamSize(),t.getMaxTeams(),teams,t.getEntryFee());}}
